package org.dextur.reputation.probe;

import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.policy.AdministrationData;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;

/** Isolated native protocol clients, real commands/attributes/services and full optional integrations. */
final class PolicyRuntimeProbe {
    private final JavaPlugin plugin;private final ReputationPolicyService service;private final VotingService voting;private final RecoveryService recovery;private final ReputationApplication app;private final PolicyApplication administration;
    private final NamespacedKey own=new NamespacedKey("dexturreputation","reputation-health"),foreign=new NamespacedKey("phase6qa","foreign-health");
    private Player operator,voter,target;private Object initialTrust;private final List<ReputationPolicyService.Changed> events=new CopyOnWriteArrayList<>();
    PolicyRuntimeProbe(JavaPlugin plugin)throws Exception{this.plugin=plugin;service=plugin.getServer().getServicesManager().load(ReputationPolicyService.class);voting=plugin.getServer().getServicesManager().load(VotingService.class);recovery=plugin.getServer().getServicesManager().load(RecoveryService.class);app=(ReputationApplication)plugin.getServer().getServicesManager().load(ReputationService.class);var owner=plugin.getServer().getPluginManager().getPlugin("DexturReputation");var accessor=owner.getClass().getDeclaredMethod("policyAdministration");accessor.setAccessible(true);administration=(PolicyApplication)accessor.invoke(owner);}
    void start(Runnable success,Consumer<Throwable> failed){Path marker=plugin.getDataFolder().toPath().resolve("policy-restart.txt");boolean restart=Files.exists(marker);AutoCloseable listener=service.onChanged(events::add);
        poll(()->main(()->{operator=plugin.getServer().getPlayerExact("Phase6Admin");voter=plugin.getServer().getPlayerExact("Phase6Voter");target=plugin.getServer().getPlayerExact("Phase6Target");return operator!=null&&voter!=null&&target!=null;}),Boolean::booleanValue,0)
        .thenCompose(v->main(()->{var attribute=target.getAttribute(Attribute.MAX_HEALTH);check(attribute!=null,"Health attribute missing");if(attribute.getModifier(foreign)==null)attribute.addTransientModifier(new AttributeModifier(foreign,4,AttributeModifier.Operation.ADD_NUMBER));target.setHealth(Math.min(24,attribute.getValue()));operator.performCommand("rep language en_US");return true;}))
        .thenCompose(v->poll(()->main(()->app.cachedLanguage(operator.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.en_US),Boolean::booleanValue,0))
        .thenCompose(v->poll(this::trust,Objects::nonNull,0)).thenCompose(value->{initialTrust=value;return administration.administration(target.getUniqueId());})
        .thenCompose(state->{if(restart){try{check(state!=null&&state.contribution()==100,"Admin aggregate lost across restart");String saved=state.audit().size()+"/"+state.audit().getLast().request().operation();check(Files.readString(marker).equals(saved),"Restart duplicated administration audit");}catch(Exception e){return CompletableFuture.failedFuture(e);}return service.evaluate(voter.getUniqueId(),"reputation.vote").thenApply(r->{check(r.decision()==ReputationPolicyResult.Decision.DENY,"Offline lock lost across restart");check(events.isEmpty(),"Restart replayed policy effects");return true;});}return firstRun();})
        .thenCompose(v->service.evaluate(target.getUniqueId(),"health.maximum"))
        .thenCompose(v->poll(()->main(()->{var attribute=target.getAttribute(Attribute.MAX_HEALTH);return Math.abs(attribute.getValue()-25)<0.000001&&attribute.getModifiers().stream().filter(m->m.getKey().equals(own)).count()==1;}),Boolean::booleanValue,0))
        .thenCompose(v->guiAndLocales())
        .thenCompose(v->administrativeLocales())
        .thenCompose(v->reloadAndHealth())
        .thenCompose(v->trust()).thenCompose(value->{check(value.equals(initialTrust),"Administrative score mutation modified target Trust");return recovery.status(target.getUniqueId());})
        .thenCompose(snapshot->{check(snapshot.rewards().isEmpty(),"Administration created or erased recovery rewards");return voting.view(target.getUniqueId());})
        .thenCompose(view->{check(view.profile().visibleScore()==100&&view.profile().communityScore()==0,"Final public/admin projection wrong");check(view.statistics().historyEntries()==4,"Administrative commands created fake votes");check(view.profile().tier().equals("RESPECTED"),"Administrative tier reconciliation missing");return plugin.getServer().getPluginManager().isPluginEnabled("LuckPerms")?new LuckPermsRuntimeProbe(plugin).verifyOnline(target.getUniqueId()):CompletableFuture.completedFuture(null);})
        .thenCompose(v->service.evaluate(target.getUniqueId(),"health.maximum"))
        .thenCompose(v->service.evaluate(voter.getUniqueId(),"reputation.vote"))
        .thenCompose(v->poll(()->main(()->verifyPapi()),Boolean::booleanValue,0))
        .thenCompose(v->administration.administration(target.getUniqueId())).thenCompose(state->main(()->{check(state.audit().stream().anyMatch(a->a.request().actor().equals(operator.getUniqueId().toString())),"Player administrator UUID missing");check(state.audit().stream().anyMatch(a->a.request().actor().equals("CONSOLE")),"Console actor missing");Files.createDirectories(marker.getParent());Files.writeString(marker,state.audit().size()+"/"+state.audit().getLast().request().operation());target.performCommand("rep policies");plugin.getLogger().info("PROBE_POLICIES_PASS: native administration, lock/unlock/offline, exact set/add/remove, no fake votes, concurrent vote/admin, Trust/recovery preservation, tiers, health ownership/reload, GUI/locales and restart");return true;}))
        .whenComplete((v,error)->main(()->{try{listener.close();if(error!=null)failed.accept(error);else success.run();}catch(Throwable failure){failed.accept(failure);}return null;}));
    }
    private CompletionStage<Boolean> firstRun(){
        return main(()->{operator.performCommand("repadmin set Phase6Target 999 denied");return true;}).thenCompose(v->voting.view(target.getUniqueId())).thenCompose(view->{check(view.profile().visibleScore()==0,"Permission denial mutated reputation");return main(()->{var permission=operator.addAttachment(plugin,"dexturreputation.admin.set",true);operator.performCommand("repadmin set Phase6Target -100 Player UUID audit");permission.remove();return true;});})
        .thenCompose(v->score(-100)).thenCompose(v->poll(()->main(()->target.getAttribute(Attribute.MAX_HEALTH).getValue()==22&&target.getHealth()>0&&target.getHealth()<=22),Boolean::booleanValue,0))
        .thenCompose(v->console("repadmin add Phase6Target +25 signed addition")).thenCompose(v->score(-75))
        .thenCompose(v->console("repadmin remove Phase6Target 25 magnitude subtraction")).thenCompose(v->score(-100))
        .thenCompose(v->console("repadmin remove Phase6Target -25 invalid magnitude")).thenCompose(v->score(-100))
        .thenCompose(v->console("repadmin set Phase6Target +100 visible target")).thenCompose(v->score(100))
        .thenCompose(v->console("repadmin add Phase6Target -50 signed reduction")).thenCompose(v->score(50))
        .thenCompose(v->console("repadmin add Phase6Target +50 restoration")).thenCompose(v->score(100))
        .thenCompose(v->console("repadmin voting lock Phase6Voter administrative lock"))
        .thenCompose(v->poll(()->service.evaluate(voter.getUniqueId(),"reputation.vote"),r->r.decision()==ReputationPolicyResult.Decision.DENY,0))
        .thenCompose(v->main(()->{voter.performCommand("like Phase6Target helpful blocked");voter.performCommand("dislike Phase6Target rude blocked");return true;}))
        .thenCompose(v->voting.submit(cast(VoteType.POSITIVE)).handle((receipt,error)->{check(root(error) instanceof PolicyDeniedException,"Like lock bypassed");return true;}))
        .thenCompose(v->voting.submit(cast(VoteType.NEGATIVE)).handle((receipt,error)->{check(root(error) instanceof PolicyDeniedException,"Dislike lock bypassed");return true;}))
        .thenCompose(v->poll(()->main(()->((VotingApplication)voting).pendingOperations()==0),Boolean::booleanValue,0))
        .thenCompose(v->voting.view(target.getUniqueId())).thenApply(view->{check(view.statistics().historyEntries()==0,"Native commands passed the held voting lock");return true;})
        .thenCompose(v->console("repadmin voting unlock Phase6Voter normal eligibility restored"))
        .thenCompose(v->poll(()->service.evaluate(voter.getUniqueId(),"reputation.vote"),ReputationPolicyResult::permitted,0))
        .thenCompose(v->main(()->{voter.performCommand("like Phase6Target helpful legitimate vote");return true;}))
        .thenCompose(v->poll(()->voting.view(target.getUniqueId()),view->view.statistics().historyEntries()==1,0))
        .thenCompose(v->voting.submit(revoke()))
        .thenCompose(v->{var vote=voting.submit(cast(VoteType.POSITIVE));var adjust=administration.administer(request(AdministrationData.Type.ADD,1));return vote.thenCombine(adjust,(a,b)->true);})
        .thenCompose(v->score(102)).thenCompose(v->voting.submit(revoke()))
        .thenCompose(v->console("repadmin set Phase6Target 100 final projection")).thenCompose(v->score(100))
        .thenCompose(v->{var operation=request(AdministrationData.Type.ADD,0);return administration.administer(operation).thenCombine(administration.administer(operation),(a,b)->{check(a.duplicate()!=b.duplicate(),"Duplicate adjustment audit/reward");return true;});})
        .thenCompose(v->main(()->{voter.kick(Component.text("QA known offline administrative target"));return true;}))
        .thenCompose(v->poll(()->main(()->plugin.getServer().getPlayer(voter.getUniqueId())==null),Boolean::booleanValue,0))
        .thenCompose(v->console("repadmin voting lock Phase6Voter offline persistent lock"))
        .thenCompose(v->poll(()->service.evaluate(voter.getUniqueId(),"reputation.vote"),r->r.decision()==ReputationPolicyResult.Decision.DENY,0))
        .thenCompose(v->console("repadmin policy Phase6Target chat.send deny QA policy override"))
        .thenCompose(v->poll(()->service.evaluate(target.getUniqueId(),"chat.send"),r->r.decision()==ReputationPolicyResult.Decision.DENY,0))
        .thenCompose(v->console("repadmin policy Phase6Target chat.send reset QA policy reset"))
        .thenCompose(v->poll(()->service.evaluate(target.getUniqueId(),"chat.send"),ReputationPolicyResult::permitted,0))
        .thenCompose(v->console("repadmin policy Phase6Voter reputation.vote allow cannot bypass voting lock"))
        .thenCompose(v->poll(()->service.evaluate(voter.getUniqueId(),"reputation.vote"),r->r.decision()==ReputationPolicyResult.Decision.DENY,0))
        .thenCompose(v->console("repadmin policy Phase6Voter reputation.vote reset restore default policy"))
        .thenCompose(v->poll(()->service.evaluate(voter.getUniqueId(),"reputation.vote"),r->r.decision()==ReputationPolicyResult.Decision.DENY,0)).thenApply(v->true);
    }
    private AdministrationData.Request request(AdministrationData.Type type,long amount){return new AdministrationData.Request(UUID.randomUUID(),target.getUniqueId(),"global",type,amount,"",AdministrationData.Override.DEFAULT,"CONSOLE","QA concurrent/idempotent operation",Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS));}
    private VoteRequest cast(VoteType type){return new VoteRequest(UUID.randomUUID(),voter.getUniqueId(),target.getUniqueId(),VoteRequest.Action.SUBMIT,type,type==VoteType.POSITIVE?"helpful":"rude","Phase 6 native QA");}
    private VoteRequest revoke(){return new VoteRequest(UUID.randomUUID(),voter.getUniqueId(),target.getUniqueId(),VoteRequest.Action.REVOKE,null,"","Phase 6 revoke");}
    private CompletionStage<Boolean> score(long expected){return poll(()->voting.view(target.getUniqueId()),view->view.profile().visibleScore()==expected,0).thenApply(v->true);}
    private CompletionStage<Boolean> console(String command){return main(()->{plugin.getServer().dispatchCommand(plugin.getServer().getConsoleSender(),command);return true;});}
    private CompletionStage<Boolean> administrativeLocales(){var ru=new CopyOnWriteArrayList<String>();var en=new CopyOnWriteArrayList<String>();return main(()->{for(boolean english:List.of(false,true)){var replies=english?en:ru;var sender=(CommandSender)java.lang.reflect.Proxy.newProxyInstance(plugin.getClass().getClassLoader(),new Class<?>[]{english?Player.class:CommandSender.class},(proxy,method,args)->{if(method.getName().equals("sendMessage")&&args!=null)for(Object value:args)if(value instanceof Component component)replies.add(plain(component));return switch(method.getName()){case "hasPermission","isPermissionSet","isOp","isOnline"->true;case "getUniqueId"->operator.getUniqueId();case "getName","toString"->"Phase6LocaleProbe";case "getServer"->plugin.getServer();case "hashCode"->System.identityHashCode(proxy);case "equals"->proxy==args[0];default->method.getReturnType()==boolean.class?false:null;};});plugin.getServer().getPluginCommand("repadmin").execute(sender,"repadmin",new String[]{"voting","status",voter.getName()});}return true;}).thenCompose(v->poll(()->main(()->!ru.isEmpty()&&!en.isEmpty()),Boolean::booleanValue,0)).thenCompose(v->main(()->{check(ru.stream().anyMatch(text->text.contains("голосование")&&text.contains(voter.getName())),"RU administrative interpolation failed: "+ru);check(en.stream().anyMatch(text->text.contains("voting is")&&text.contains(voter.getName())),"EN administrative interpolation failed: "+en);plugin.getLogger().info("PROBE_ADMIN_LOCALES_PASS: real registered admin command emits substituted RU/EN replies");return true;}));}
    private CompletionStage<Boolean> guiAndLocales(){return main(()->{target.performCommand("rep language en_US");return true;}).thenCompose(v->poll(()->main(()->app.cachedLanguage(target.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.en_US),Boolean::booleanValue,0)).thenCompose(v->main(()->{target.performCommand("rep policies");return true;})).thenCompose(v->poll(()->main(()->{var inventory=target.getOpenInventory().getTopInventory();return plain(target.getOpenInventory().title()).equals("Reputation effects")&&inventory.getItem(0)!=null&&inventory.getItem(19)!=null;}),Boolean::booleanValue,0)).thenCompose(v->main(()->{var click=new org.bukkit.event.inventory.InventoryClickEvent(target.getOpenInventory(),org.bukkit.event.inventory.InventoryType.SlotType.CONTAINER,0,org.bukkit.event.inventory.ClickType.SHIFT_LEFT,org.bukkit.event.inventory.InventoryAction.MOVE_TO_OTHER_INVENTORY);plugin.getServer().getPluginManager().callEvent(click);check(click.isCancelled(),"Policy GUI inventory transfer permitted");target.closeInventory();target.performCommand("rep language ru_RU");return true;})).thenCompose(v->poll(()->main(()->app.cachedLanguage(target.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.ru_RU),Boolean::booleanValue,0)).thenCompose(v->main(()->{target.performCommand("rep policies");return true;})).thenCompose(v->poll(()->main(()->plain(target.getOpenInventory().title()).equals("Последствия репутации")&&target.getOpenInventory().getTopInventory().getItem(0)!=null),Boolean::booleanValue,0)).thenCompose(v->main(()->{target.closeInventory();return true;}));}
    private CompletionStage<Boolean> reloadAndHealth(){Path file=plugin.getServer().getPluginManager().getPlugin("DexturReputation").getDataFolder().toPath().resolve("features.yml");String original;try{original=Files.readString(file);}catch(Exception e){return CompletableFuture.failedFuture(e);}var accepted=administration.configuration();return main(()->{Files.writeString(file,"config-version: 1\nhealth: {enabled: invalid}\n");return true;}).thenCompose(v->administration.reload(file.getParent()).handle((ok,error)->{check(error!=null&&administration.configuration()==accepted,"Invalid reload replaced working policy");return true;})).thenCompose(v->main(()->{Files.writeString(file,"config-version: 1\nhealth: {enabled: false}\n");return true;})).thenCompose(v->administration.reload(file.getParent())).thenCompose(v->poll(()->main(()->target.getAttribute(Attribute.MAX_HEALTH).getModifiers().stream().noneMatch(m->m.getKey().equals(own))),Boolean::booleanValue,0)).thenCompose(v->main(()->{check(target.getAttribute(Attribute.MAX_HEALTH).getModifier(foreign)!=null,"Foreign health modifier removed during reload");Files.writeString(file,original);return true;})).thenCompose(v->administration.reload(file.getParent())).thenCompose(v->poll(()->main(()->{var a=target.getAttribute(Attribute.MAX_HEALTH);return a.getValue()==25&&a.getModifiers().stream().filter(m->m.getKey().equals(own)).count()==1&&target.getHealth()>0&&target.getHealth()<=a.getValue();}),Boolean::booleanValue,0));}
    @SuppressWarnings("unchecked") private CompletionStage<Object> trust(){try{var owner=plugin.getServer().getPluginManager().getPlugin("DexturReputation");var method=owner.getClass().getDeclaredMethod("protectionAdministration");method.setAccessible(true);var capability=method.invoke(owner);return (CompletionStage<Object>)capability.getClass().getMethod("trust",UUID.class).invoke(capability,target.getUniqueId());}catch(Exception e){return CompletableFuture.failedFuture(e);}}
    private boolean verifyPapi()throws Exception{if(!plugin.getServer().getPluginManager().isPluginEnabled("PlaceholderAPI"))return true;var papi=plugin.getServer().getPluginManager().getPlugin("PlaceholderAPI");var type=Class.forName("me.clip.placeholderapi.PlaceholderAPI",true,papi.getClass().getClassLoader());var method=type.getMethod("setPlaceholders",org.bukkit.OfflinePlayer.class,String.class);String health=String.valueOf(method.invoke(null,target,"%dexturreputation_health_modifier%"));if(health.isEmpty())return false;check(health.equals("1"),"PAPI actual health modifier: "+health);check(method.invoke(null,target,"%dexturreputation_policy_chat_send%").equals("ALLOW"),"Chat policy PAPI");var locked=plugin.getServer().getOfflinePlayer(voter.getUniqueId());check(method.invoke(null,locked,"%dexturreputation_policy_vote%").equals("DENY"),"Voting lock policy PAPI");plugin.getLogger().info("PROBE_POLICY_PAPI_PASS: actual owned health and cache-only vote/chat policies through full parser");return true;}
    private static String plain(Component text){return PlainTextComponentSerializer.plainText().serialize(text);}
    private static Throwable root(Throwable error){if(error==null)return null;while(error.getCause()!=null&&error.getCause()!=error)error=error.getCause();return error;}
    private <T> CompletableFuture<T> main(Callable<T> action){var result=new CompletableFuture<T>();Runnable task=()->{try{result.complete(action.call());}catch(Throwable e){result.completeExceptionally(e);}};if(Bukkit.isPrimaryThread())task.run();else plugin.getServer().getScheduler().runTask(plugin,task);return result;}
    private <T> CompletionStage<T> poll(Supplier<? extends CompletionStage<T>> read,Predicate<T> ready,int attempt){return read.get().thenCompose(value->{if(ready.test(value))return CompletableFuture.completedFuture(value);if(attempt>200)return CompletableFuture.failedFuture(new AssertionError("Policy runtime wait timed out at "+value));var result=new CompletableFuture<T>();plugin.getServer().getScheduler().runTaskLater(plugin,()->poll(read,ready,attempt+1).whenComplete((next,error)->{if(error==null)result.complete(next);else result.completeExceptionally(error);}),2L);return result;});}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
}
